import type { ReactElement } from "react";
import type { ViewProps } from "react-native";
import Animated, { useAnimatedStyle } from "react-native-reanimated";
import { useSliderPart } from "./slider.context";
import { fillBounds, fillExtent, sliderVariants } from "./slider.variants";

export type SliderFillProps = Omit<ViewProps, "children" | "style"> & {
	className?: string;
};

/**
 * The painted part of the groove.
 *
 * A lone thumb fills from the start of the track, because that is what a single
 * value means — how far along. A range fills *between* its own thumbs, because
 * the ends are what the caller excluded. {@link fillBounds} is that decision and
 * is pure, so `bun test` sweeps it.
 *
 * **The far end lands on the thumb's far edge**, which is what makes both extremes
 * exact: one thumb's width of fill at the minimum, so the handle covers it
 * completely and a slider at rest shows a plain track, and the track's full length
 * at the maximum, with no sliver of empty groove past the handle. That works only
 * because the thumb's diameter is the track's thickness — {@link fillExtent} is
 * where the arithmetic lives, and where `bun test` can hold it down.
 *
 * The extent is an animated style rather than a class because it is a measured
 * length in points, and a class cannot name one. The *colour* is a class, which
 * is what keeps the whole colour matrix inside `bun test`.
 *
 * Nothing here reads React state: the fill follows the shared value the pan
 * writes, so it tracks the finger at the display's refresh rate rather than at
 * React's.
 */
export function SliderFill({ className, ...props }: SliderFillProps): ReactElement {
	const { positions, trackSize, thumbSize, minValue, maxValue, orientation, color, size, isInvalid, isDisabled } =
		useSliderPart("Slider.Fill");
	const isVertical = orientation === "vertical";

	const fillStyle = useAnimatedStyle(() => {
		const thumb = thumbSize.value;
		const values = positions.value;
		const bounds = fillBounds(values, minValue, maxValue);
		// Both helpers hold themselves at zero until the layouts have landed. A
		// measured 0 means "not measured yet", never "a track with no length", and
		// dividing into it would put NaN on the UI thread — which no later frame
		// recovers from.
		const { offset, extent } = fillExtent({
			end: bounds.end,
			isRange: values.length > 1,
			start: bounds.start,
			thumbSize: thumb,
			travel: trackSize.value - thumb,
		});

		// The same keys every frame, so Reanimated is never asked to swap a style's
		// shape mid-animation.
		return isVertical ? { bottom: offset, height: extent } : { left: offset, width: extent };
	});

	return (
		<Animated.View
			className={sliderVariants({ color, isDisabled, isInvalid, orientation, size }).fill({ className })}
			style={fillStyle}
			{...props}
		/>
	);
}
SliderFill.displayName = "DelacourUI.Slider.Fill";

import type { ReactElement } from "react";
import { Text, type TextPresetProps } from "@registry/ui/text";
import { useSliderPart } from "./slider.context";
import type { SliderRenderChildren } from "./slider.types";
import { formatSliderValue, SLIDER_OUTPUT_TEXT_SIZE, sliderVariants } from "./slider.variants";

export type SliderOutputProps = Omit<TextPresetProps, "children"> & {
	/** Custom content, or a function called with the slider's settled state. */
	children?: SliderRenderChildren;
};

/**
 * The current value, formatted.
 *
 * Renders `Text.Label` and names a size, never a scale of its own. The weight and
 * the colour belong to the preset — restating them here would be a second
 * definition of `Text.Label` that could drift from it, the rule `Field` is built
 * on. Naming the size is what lets the readout still track the slider's own axis,
 * since `Text`'s size axis is built to beat its preset.
 *
 * A range is joined with an en dash. `formatOptions` goes straight to
 * `Intl.NumberFormat`, so a currency or a percentage needs nothing but the
 * options object the platform already understands.
 *
 * **It reads React state, not the shared value the thumb reads**, and that is the
 * one place in this component where a value crosses back to the JS thread during
 * a drag. `Intl` is not available to a worklet, so a formatted readout cannot be
 * derived on the UI thread without giving up `formatOptions` entirely. The cost
 * is bounded instead: the pan snaps on the UI thread and only a *changed* snapped
 * value is mirrored across, so a full-width drag at the default step is a few
 * dozen commits. A continuous slider — `step={0}` — has no stops to change on and
 * does re-render per frame; if that ever profiles badly, the escape hatch is an
 * `Animated.Text` fed by a `useDerivedValue`, which `Text` already renders and
 * which trades `formatOptions` away.
 */
export function SliderOutput({ children, className, size, ...props }: SliderOutputProps): ReactElement {
	const context = useSliderPart("Slider.Output");
	const { color, size: sliderSize, isDisabled, isInvalid, orientation, values, formatOptions } = context;

	const content =
		typeof children === "function"
			? children(context.renderProps)
			: (children ?? formatSliderValue(values, formatOptions));

	return (
		<Text.Label
			className={sliderVariants({ color, isDisabled, isInvalid, orientation, size: sliderSize }).output({ className })}
			size={size ?? SLIDER_OUTPUT_TEXT_SIZE[sliderSize]}
			{...props}
		>
			{content}
		</Text.Label>
	);
}
SliderOutput.displayName = "DelacourUI.Slider.Output";

import { type ComponentProps, type ReactElement, useCallback } from "react";
import type { AccessibilityActionEvent, LayoutChangeEvent, ViewProps } from "react-native";
import Animated, { useAnimatedStyle, useDerivedValue, withSpring } from "react-native-reanimated";
import { useSliderPart } from "./slider.context";
import {
	formatSliderValue,
	progressOf,
	SLIDER_THUMB_ANIMATION,
	SLIDER_THUMB_SPRING,
	sliderVariants,
} from "./slider.variants";

/** What one press of an assistive increment moves the value by, when `step` is continuous. */
const CONTINUOUS_ACCESSIBILITY_STEPS = 10;

export type SliderThumbProps = Omit<ViewProps, "children" | "style"> & {
	/** Which value this thumb drives. `0` unless the slider holds a range. */
	index?: number;
	className?: string;
	/**
	 * Passed to the knob inside the capsule.
	 *
	 * A prop rather than a `classNames` map, which is the shape `Radio.Indicator`
	 * already uses for its dot: one escape hatch, named after the thing it reaches,
	 * and it carries every `View` prop rather than only a class.
	 */
	knobProps?: Omit<ComponentProps<typeof Animated.View>, "children" | "className" | "style"> & { className?: string };
};

/**
 * The grab handle.
 *
 * **It holds no gesture of its own**, which is the design rather than an
 * omission. One `Gesture.Pan()` on the track drives every thumb: a press 40pt
 * along an empty groove should still lift the thumb it is about to move, and a
 * per-thumb gesture could not know that. It would also nest a descendant handler
 * inside the track's, leaving two recognisers to negotiate for one drag.
 *
 * **One animated style, one node.** The position and the grabbed scale are two
 * entries in a single `transform`, because two `useAnimatedStyle` calls on one
 * view fight for the same prop and the later one silently wins — the rule
 * `Radio.Indicator` states, and the reason `Pressable` cannot be the thing that
 * moves here.
 *
 * The scale is a `useDerivedValue` rather than a branch inside the position
 * style: it depends only on which thumb is being dragged, so deriving it
 * separately means the spring is evaluated when the grab changes rather than on
 * every frame of the drag.
 *
 * **It is invisible until the track has been measured.** Both layouts arrive a
 * commit or two after mount, and a thumb drawn before then sits at a garbage
 * offset for a frame — which reads as a flicker on every mount.
 *
 * **The accessibility surface lives here**, and it is the whole of the control
 * for anyone not using a finger. `adjustable` plus a value is what VoiceOver and
 * TalkBack read; the increment and decrement actions are what their swipe
 * gestures call. Without them a slider with no gesture on its thumb would have no
 * assistive path to its value at all.
 */
export function SliderThumb({ index = 0, className, knobProps, ...props }: SliderThumbProps): ReactElement {
	const {
		positions,
		trackSize,
		thumbSize,
		activeIndex,
		values,
		minValue,
		maxValue,
		step,
		formatOptions,
		orientation,
		color,
		size,
		isInvalid,
		isDisabled,
		updateValue,
	} = useSliderPart("Slider.Thumb");
	const isVertical = orientation === "vertical";
	const slots = sliderVariants({ color, isDisabled, isInvalid, orientation, size });

	const handleLayout = useCallback(
		(event: LayoutChangeEvent) => {
			// Every thumb writes the same number — they are one size — so the last
			// one to lay out wins with the value all of them hold.
			thumbSize.value = isVertical ? event.nativeEvent.layout.height : event.nativeEvent.layout.width;
		},
		[isVertical, thumbSize]
	);

	// The capsule carries the position and the knob carries the squeeze, on two
	// different nodes. Two animated styles on *one* node fight for the same prop
	// and the later one silently wins — the rule `Radio.Indicator` states — and
	// scaling the capsule would push it past the track it sits flush inside.
	const thumbStyle = useAnimatedStyle(() => {
		const measured = trackSize.value;
		const travel = measured - thumbSize.value;
		const progress = progressOf(positions.value[index] ?? minValue, minValue, maxValue);
		const offset = travel <= 0 ? 0 : progress * travel;

		return {
			opacity: measured > 0 ? 1 : 0,
			// A vertical slider counts up from the bottom, so the handle is anchored
			// there and travels the other way. This sign and `valueFromOffset`'s
			// inversion are the only two places the axis turns around.
			transform: isVertical ? [{ translateY: -offset }] : [{ translateX: offset }],
		};
	});

	// Derived rather than branched inside the style above: it depends only on which
	// thumb is being dragged, so the spring is evaluated when the grab changes
	// rather than on every frame of the drag.
	const scale = useDerivedValue(() =>
		withSpring(
			activeIndex.value === index ? SLIDER_THUMB_ANIMATION.grabbedScale : SLIDER_THUMB_ANIMATION.restScale,
			SLIDER_THUMB_SPRING
		)
	);
	const knobStyle = useAnimatedStyle(() => ({ transform: [{ scale: scale.value }] }));

	const value = values[index] ?? minValue;
	const nudge = step > 0 ? step : (maxValue - minValue) / CONTINUOUS_ACCESSIBILITY_STEPS;

	const handleAccessibilityAction = useCallback(
		(event: AccessibilityActionEvent) => {
			const direction = event.nativeEvent.actionName === "increment" ? 1 : -1;
			updateValue(index, value + direction * nudge);
		},
		[index, nudge, updateValue, value]
	);

	return (
		<Animated.View
			accessibilityActions={ACCESSIBILITY_ACTIONS}
			accessibilityRole="adjustable"
			accessibilityState={{ disabled: isDisabled }}
			accessibilityValue={{
				max: maxValue,
				min: minValue,
				now: value,
				text: formatSliderValue([value], formatOptions),
			}}
			accessible
			className={slots.thumb({ className })}
			onAccessibilityAction={handleAccessibilityAction}
			onLayout={handleLayout}
			style={thumbStyle}
			{...props}
		>
			<Animated.View {...knobProps} className={slots.knob({ className: knobProps?.className })} style={knobStyle} />
		</Animated.View>
	);
}
SliderThumb.displayName = "DelacourUI.Slider.Thumb";

/**
 * The two actions an assistive swipe on an `adjustable` maps to.
 *
 * Module scope on purpose: a fresh array each render is a new prop every commit,
 * and React Native sends the whole accessibility config across on any change.
 */
const ACCESSIBILITY_ACTIONS = [{ name: "increment" }, { name: "decrement" }] as const;

import { type ReactElement, useCallback, useMemo } from "react";
import type { LayoutChangeEvent, ViewProps } from "react-native";
import { Gesture, GestureDetector } from "react-native-gesture-handler";
import Animated, { useAnimatedReaction, useSharedValue } from "react-native-reanimated";
import { scheduleOnRN } from "react-native-worklets";
import { playHaptic } from "@registry/ui/pressable";
import { useSliderPart } from "./slider.context";
import type { SliderRenderChildren } from "./slider.types";
import {
	clampThumb,
	nearestThumbIndex,
	shouldTickHaptic,
	sliderVariants,
	snapToStep,
	valueFromOffset,
} from "./slider.variants";

export type SliderTrackProps = Omit<ViewProps, "children" | "style"> & {
	/**
	 * The fill and the thumbs. A function is called with the slider's settled
	 * state, which is how a range maps over its own values.
	 */
	children?: SliderRenderChildren;
	className?: string;
};

/**
 * The groove the thumbs run along, and the surface the drag is claimed on.
 *
 * This is where the whole gesture lives. One `Gesture.Pan()` drives every thumb:
 * touching down grabs the nearest one and moves it to the finger, and from there
 * the drag tracks it. One rule rather than a tap mode and a drag mode — the
 * alternative, dragging the handle only, is what iOS's own slider does and it is
 * a poor trade on a wide track, where the thumb is usually nowhere near where you
 * are pointing.
 *
 * **The value is written in `onBegin`, not only in `onUpdate`.** A pan activates
 * on the first *movement*, so a stationary tap never reaches `onStart` or
 * `onUpdate` at all — a slider that only computed there would tick, lift its
 * thumb and then not move it. `onFinalize` is likewise where the drag is reported
 * as finished, because it is the one callback that fires on every path, including
 * the one where the pan never activated.
 *
 * **`minDistance(0)` is what wins the touch from a scroll view.**
 * `Screen.ScrollArea` renders React Native's own `ScrollView`, not Gesture
 * Handler's, so there is no handler to negotiate with — the two race, and a pan
 * that activates on the first move beats a scroll view's ten-point slop on both
 * platforms. It is also why there is no `activeOffsetX` here: waiting for the
 * axis to declare itself would hand the scroll the first move and put a dead zone
 * at the start of every drag. `blocksExternalGesture` is not the answer either —
 * it resolves a ref to a handler tag, a plain `ScrollView` has none, and the call
 * is dropped without an error.
 *
 * **`shouldCancelWhenOutside(false)`** where `Pressable`'s tap sets it `true`:
 * dragging a thumb to the far end routinely leaves the track's bounds, and the
 * value must keep tracking rather than the gesture giving up.
 *
 * The mirror back to React is deliberately thin. `positions` is written on the UI
 * thread at the display's refresh rate; only a *changed* set of snapped values is
 * scheduled across, so a whole-track drag at the default step is a few dozen
 * commits rather than one per frame.
 */
export function SliderTrack({ children, className, ...props }: SliderTrackProps): ReactElement {
	const {
		positions,
		trackSize,
		thumbSize,
		activeIndex,
		minValue,
		maxValue,
		step,
		haptic,
		orientation,
		color,
		size,
		isInvalid,
		isDisabled,
		commitValues,
		commitEnd,
		setDragging,
		renderProps,
	} = useSliderPart("Slider.Track");
	const isVertical = orientation === "vertical";

	// What the last haptic reported, and where the finger was when it did. Both
	// feed `shouldTickHaptic`, which is what keeps a flick across a fine step scale
	// from firing a hundred times.
	const lastTick = useSharedValue(Number.NaN);
	const lastTickPosition = useSharedValue(0);

	const handleLayout = useCallback(
		(event: LayoutChangeEvent) => {
			trackSize.value = isVertical ? event.nativeEvent.layout.height : event.nativeEvent.layout.width;
		},
		[isVertical, trackSize]
	);

	const gesture = useMemo(() => {
		// Declared here rather than at module scope, and called only from the two
		// callbacks below. A worklet defined beside its callers in one scope is
		// captured by ordinary closure; a module-scope one binds at import time, in
		// source order, which is how a helper ends up `undefined` on the UI thread.
		const applyTouch = (along: number, forIndex: number, isGrab: boolean) => {
			"worklet";
			const thumb = thumbSize.value;
			const travel = trackSize.value - thumb;
			// The touch is read in the thumb's own frame — its centre, not its left
			// edge — so the handle stays inside the groove at both ends.
			const position = along - thumb / 2;
			const raw = valueFromOffset({ position, travel, minValue, maxValue, isVertical });
			const snapped = snapToStep(raw, step, minValue, maxValue);
			const current = positions.value;
			const next = clampThumb(snapped, current, forIndex, minValue, maxValue);

			if (next !== current[forIndex]) {
				const updated = [...current];
				updated[forIndex] = next;
				positions.value = updated;
			}

			// The grab itself always confirms, the way a press does. After that the
			// ticks are the step crossings, rate-limited by distance travelled.
			if (isGrab) {
				lastTick.value = next;
				lastTickPosition.value = position;
				if (haptic !== false) playHaptic(haptic);
				return;
			}

			if (
				haptic !== false &&
				shouldTickHaptic({
					lastPosition: lastTickPosition.value,
					lastSnapped: lastTick.value,
					maxValue,
					minValue,
					position,
					snapped: next,
					step,
				})
			) {
				playHaptic(haptic);
				lastTick.value = next;
				lastTickPosition.value = position;
			}
		};

		return Gesture.Pan()
			.enabled(!isDisabled)
			.minDistance(0)
			.shouldCancelWhenOutside(false)
			.onBegin((event) => {
				"worklet";
				const along = isVertical ? event.y : event.x;
				const thumb = thumbSize.value;
				const raw = valueFromOffset({
					isVertical,
					maxValue,
					minValue,
					position: along - thumb / 2,
					travel: trackSize.value - thumb,
				});
				const index = nearestThumbIndex(positions.value, raw);
				activeIndex.value = index;
				scheduleOnRN(setDragging, true);
				applyTouch(along, index, true);
			})
			.onUpdate((event) => {
				"worklet";
				const index = activeIndex.value;
				if (index < 0) return;
				applyTouch(isVertical ? event.y : event.x, index, false);
			})
			.onFinalize(() => {
				"worklet";
				activeIndex.value = -1;
				// Order matters: the root must have stopped treating this as a live
				// drag before `commitEnd` asks it to re-sync. `scheduleOnRN` keeps
				// them in the order they were queued.
				scheduleOnRN(setDragging, false);
				scheduleOnRN(commitEnd, [...positions.value]);
			});
	}, [
		activeIndex,
		commitEnd,
		haptic,
		isDisabled,
		isVertical,
		lastTick,
		lastTickPosition,
		maxValue,
		minValue,
		positions,
		setDragging,
		step,
		thumbSize,
		trackSize,
	]);

	// The one hop from the UI thread back to React, and it is gated element-wise:
	// `useAnimatedReaction` re-runs on every write, and `positions` is a fresh
	// array each time, so identity says nothing about whether the value moved.
	useAnimatedReaction(
		() => positions.value,
		(current, previous) => {
			if (previous !== null && current.length === previous.length) {
				let changed = false;
				for (let index = 0; index < current.length; index++) {
					if (current[index] !== previous[index]) {
						changed = true;
						break;
					}
				}
				if (!changed) return;
			}
			scheduleOnRN(commitValues, [...current]);
		},
		[commitValues]
	);

	const slots = sliderVariants({ color, isDisabled, isInvalid, orientation, size });

	return (
		<GestureDetector gesture={gesture}>
			<Animated.View className={slots.touchArea()} {...props}>
				<Animated.View className={slots.track({ className })} onLayout={handleLayout}>
					{typeof children === "function" ? children(renderProps) : children}
				</Animated.View>
			</Animated.View>
		</GestureDetector>
	);
}
SliderTrack.displayName = "DelacourUI.Slider.Track";

import { createContext, type ReactElement, type ReactNode, use } from "react";
import type { SharedValue } from "react-native-reanimated";
import type { HapticFeedback } from "@registry/ui/pressable";
import type { SliderRenderProps } from "./slider.types";
import type { SliderColor, SliderOrientation, SliderSize } from "./slider.variants";

export type SliderContextValue = {
	/**
	 * Every thumb's value, snapped, on the **JS thread**.
	 *
	 * What `Slider.Output` and the accessibility props read. The live position a
	 * finger is dragging lives in {@link SliderContextValue.positions} instead —
	 * these two agree at rest and lag by a mirror hop during a drag, which is the
	 * whole reason the drag never waits on React.
	 */
	values: number[];
	minValue: number;
	maxValue: number;
	/** The increment the values snap to. `0` is continuous. */
	step: number;
	orientation: SliderOrientation;
	color: SliderColor;
	size: SliderSize;
	isDisabled: boolean;
	isInvalid: boolean;
	/** Passed to `Intl.NumberFormat` by `Slider.Output`. */
	formatOptions?: Intl.NumberFormatOptions;
	/** Played as the value crosses a step. `false` silences it. */
	haptic: false | HapticFeedback;
	/**
	 * Every thumb's live value, on the **UI thread**.
	 *
	 * One shared value holding the whole array rather than one per thumb, because
	 * a thumb count is data and hooks cannot be called in a loop. Reassign it —
	 * `positions.value = next` — and never write an element in place: an array
	 * element has no setter behind it, so `positions.value[0] = x` updates nothing
	 * and fails silently.
	 */
	positions: SharedValue<number[]>;
	/** The track's own length, from its `onLayout`. `0` until it has been measured. */
	trackSize: SharedValue<number>;
	/** A thumb's diameter, from its `onLayout`. `0` until it has been measured. */
	thumbSize: SharedValue<number>;
	/** Which thumb is being dragged, or `-1` when none is. */
	activeIndex: SharedValue<number>;
	/**
	 * Writes one thumb's value from the **JS thread**, snapping and clamping it
	 * first.
	 *
	 * The one path into the value that does not go through the pan — an
	 * accessibility increment has no gesture behind it.
	 */
	updateValue: (index: number, next: number) => void;
	/**
	 * Tells the root a drag has started or finished.
	 *
	 * The root stops syncing the shared value from React state while this is true.
	 * Without it the mirror hop back from the UI thread would round-trip through a
	 * render and land on the thumb a frame late, dragging it backwards on every
	 * commit — a jitter that only shows up on a fast drag.
	 */
	setDragging: (dragging: boolean) => void;
	/** Reports a drag's new values. Called from the pan's mirror, never in render. */
	commitValues: (next: number[]) => void;
	/** Reports the values a drag settled on, once, on release. */
	commitEnd: (next: number[]) => void;
	/** The settled state a render function is handed. */
	renderProps: SliderRenderProps;
};

const SliderContext = createContext<SliderContextValue | null>(null);

/**
 * Supplies one slider's settled state to its own parts.
 *
 * Lives in its own module, importing nothing but React and types, so a part can
 * read it without importing `./slider`. That import would close a cycle, and Metro
 * serves a partially initialised module for a cycle — leaving the context
 * `undefined` at import time and red-boxing the app on a cold start.
 */
export function SliderProvider({ value, children }: { value: SliderContextValue; children: ReactNode }): ReactElement {
	return <SliderContext value={value}>{children}</SliderContext>;
}
SliderProvider.displayName = "DelacourUI.Slider.Provider";

/** The enclosing slider's state, or null outside a `<Slider>`. */
export function useSliderContext(): SliderContextValue | null {
	return use(SliderContext);
}

/**
 * Reads the enclosing slider's settled state.
 *
 * For a custom readout or a custom thumb that has to match the slider it sits in.
 * Throws outside one — use {@link useSliderContext} where the slider is optional.
 */
export function useSlider(): SliderContextValue {
	const context = useSliderContext();
	if (!context) {
		throw new Error("useSlider must be called inside a <Slider>.");
	}
	return context;
}

/**
 * The enclosing slider's state, for a compound part that cannot work without one.
 *
 * Internal: deliberately not re-exported from `index.ts`. A caller outside the
 * library wants {@link useSlider}, whose error message names the hook rather than
 * a part.
 */
export function useSliderPart(component: string): SliderContextValue {
	const context = useSliderContext();
	if (!context) {
		throw new Error(`${component} must be rendered inside a <Slider>.`);
	}
	return context;
}

import { type ReactElement, type ReactNode, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { View, type ViewProps } from "react-native";
import { useSharedValue } from "react-native-reanimated";
import { useControllableState } from "@registry/hooks/use-controllable-state";
import { useFieldContext } from "@registry/ui/field/field.context";
import type { HapticFeedback } from "@registry/ui/pressable";
import { type SliderContextValue, SliderProvider } from "./slider.context";
import type { SliderRenderProps } from "./slider.types";
import {
	clampThumb,
	fromValueArray,
	resolveSliderAxes,
	SLIDER_MAX_VALUE,
	SLIDER_MIN_VALUE,
	SLIDER_STEP,
	type SliderColor,
	type SliderOrientation,
	type SliderSize,
	sliderVariants,
	snapToStep,
	toValueArray,
} from "./slider.variants";
import { SliderFill } from "./slider-fill";
import { SliderOutput } from "./slider-output";
import { SliderThumb } from "./slider-thumb";
import { SliderTrack } from "./slider-track";

export type SliderProps = Omit<ViewProps, "children"> & {
	/** Controlled value. An array makes it a range, one thumb per entry. */
	value?: number | number[];
	/** Starting value while uncontrolled. An array makes it a range. */
	defaultValue?: number | number[];
	minValue?: number;
	maxValue?: number;
	/** The increment the value snaps to. `0` is continuous, and never ticks. */
	step?: number;
	/** Passed to `Intl.NumberFormat` by `Slider.Output`. */
	formatOptions?: Intl.NumberFormatOptions;
	/** `vertical` counts up from the bottom, and needs a definite height. */
	orientation?: SliderOrientation;
	/** What the filled part of the track means. */
	color?: SliderColor;
	size?: SliderSize;
	/** Blocks the drag and fades the control. Inherited from an enclosing `Field`. */
	isDisabled?: boolean;
	/** Reports an invalid value. Inherited from an enclosing `Field`. */
	isInvalid?: boolean;
	/** Played on grab and as the value crosses a step. `false` silences it. */
	haptic?: false | HapticFeedback;
	/** Fires on every change during the drag. */
	onChange?: (value: number | number[]) => void;
	/** Fires once, when the drag is released. Where a network write belongs. */
	onChangeEnd?: (value: number | number[]) => void;
	children?: ReactNode;
};

function SliderRoot({
	value,
	defaultValue = SLIDER_MIN_VALUE,
	minValue = SLIDER_MIN_VALUE,
	maxValue = SLIDER_MAX_VALUE,
	step = SLIDER_STEP,
	formatOptions,
	orientation,
	color,
	size,
	isDisabled,
	isInvalid,
	haptic = "selection",
	onChange,
	onChangeEnd,
	className,
	children,
	...props
}: SliderProps): ReactElement {
	const field = useFieldContext();
	const axes = resolveSliderAxes({ field, own: { color, isDisabled, isInvalid, orientation, size } });

	const [current, setCurrent] = useControllableState<number | number[]>({
		defaultValue,
		onChange,
		value,
	});

	// Which shape the caller speaks is locked on first render, exactly the way
	// `useControllableState` locks controlled versus uncontrolled — a slider that
	// silently started reporting an array to a caller holding a number would be a
	// bug with no error attached. Warn once per flip, and follow the caller rather
	// than fighting them.
	const isRangeNow = Array.isArray(value ?? defaultValue);
	const wasRange = useRef(isRangeNow);
	if (process.env.NODE_ENV !== "production" && wasRange.current !== isRangeNow) {
		console.warn(
			`Slider: switched from ${wasRange.current ? "a range" : "a single value"} to ` +
				`${isRangeNow ? "a range" : "a single value"}. Pick one for the lifetime of the component.`
		);
		wasRange.current = isRangeNow;
	}
	const isRange = wasRange.current;

	const values = useMemo(() => toValueArray(current), [current]);

	const positions = useSharedValue<number[]>(toValueArray(current));
	const trackSize = useSharedValue(0);
	const thumbSize = useSharedValue(0);
	const activeIndex = useSharedValue(-1);

	// A ref rather than state: the pan reads it a few times a drag and nothing
	// renders differently for it, so a re-render on touch-down would be pure cost.
	const isDragging = useRef(false);
	// Bumped when a drag finishes, purely to make the sync effect below run again.
	// Without it a controlled parent that *rejects* the dragged value leaves the
	// thumb where the finger let go, because `current` never changed to sync from.
	const [settledDrags, setSettledDrags] = useState(0);

	// `settledDrags` is not read in the body — being unread is the whole point of
	// it. A controlled parent that rejects a dragged value leaves `current`
	// unchanged, so without a token that moves on every release there is nothing to
	// re-run on, and the thumb stays where the finger let go rather than snapping
	// back to the value the parent actually holds.
	// biome-ignore lint/correctness/useExhaustiveDependencies: the extra dependency is the re-run trigger, see above
	useEffect(() => {
		if (isDragging.current) return;
		positions.value = toValueArray(current);
	}, [current, positions, settledDrags]);

	const setDragging = useCallback((dragging: boolean) => {
		isDragging.current = dragging;
	}, []);

	const commitValues = useCallback(
		(next: number[]) => {
			setCurrent(fromValueArray(next, isRange));
		},
		[isRange, setCurrent]
	);

	const commitEnd = useCallback(
		(next: number[]) => {
			setSettledDrags((count) => count + 1);
			onChangeEnd?.(fromValueArray(next, isRange));
		},
		[isRange, onChangeEnd]
	);

	// The one way into the value that has no gesture behind it — an assistive
	// increment. It runs the same snap and the same clamp the pan does, from the
	// JS thread, and writes both sides so the thumb moves without waiting on a
	// render.
	const valuesRef = useRef(values);
	valuesRef.current = values;

	const updateValue = useCallback(
		(index: number, next: number) => {
			const from = valuesRef.current;
			const settled = clampThumb(snapToStep(next, step, minValue, maxValue), from, index, minValue, maxValue);
			if (settled === from[index]) return;

			const updated = [...from];
			updated[index] = settled;
			positions.value = updated;
			setCurrent(fromValueArray(updated, isRange));
			onChangeEnd?.(fromValueArray(updated, isRange));
		},
		[isRange, maxValue, minValue, onChangeEnd, positions, setCurrent, step]
	);

	const renderProps = useMemo<SliderRenderProps>(
		() => ({
			isDisabled: axes.isDisabled,
			isInvalid: axes.isInvalid,
			maxValue,
			minValue,
			orientation: axes.orientation,
			step,
			values,
		}),
		[axes.isDisabled, axes.isInvalid, axes.orientation, maxValue, minValue, step, values]
	);

	const context = useMemo<SliderContextValue>(
		() => ({
			activeIndex,
			color: axes.color,
			commitEnd,
			commitValues,
			formatOptions,
			haptic,
			isDisabled: axes.isDisabled,
			isInvalid: axes.isInvalid,
			maxValue,
			minValue,
			orientation: axes.orientation,
			positions,
			renderProps,
			setDragging,
			size: axes.size,
			step,
			thumbSize,
			trackSize,
			updateValue,
			values,
		}),
		[
			activeIndex,
			axes.color,
			axes.isDisabled,
			axes.isInvalid,
			axes.orientation,
			axes.size,
			commitEnd,
			commitValues,
			formatOptions,
			haptic,
			maxValue,
			minValue,
			positions,
			renderProps,
			setDragging,
			step,
			thumbSize,
			trackSize,
			updateValue,
			values,
		]
	);

	return (
		<SliderProvider value={context}>
			<View className={sliderVariants(axes).root({ className })} {...props}>
				{children}
			</View>
		</SliderProvider>
	);
}

/**
 * A value picked by dragging along a track — one value, or a range.
 *
 * The anatomy is written out rather than assembled from props: a `Slider.Track`
 * holding a `Slider.Fill` and one `Slider.Thumb` per value, with an optional
 * `Slider.Output` above it. A range's thumb count is data, so `Slider.Track`
 * takes a function and maps over the values it is handed.
 *
 * **The whole track is the target.** Touching down grabs the nearest thumb and
 * moves it to the finger; there is no separate tap mode. `Slider.Thumb` holds no
 * gesture of its own, which is what makes a press on empty track lift the handle
 * it is about to move.
 *
 * **State works either way from one hook**: pass `value` to control it, or
 * nothing and let it hold its own. The shape is the caller's — a slider given a
 * number reports a number, one given an array reports an array — and it is locked
 * on first render.
 *
 * `onChange` fires throughout the drag; `onChangeEnd` fires once on release,
 * which is where a network write or a persisted preference belongs.
 *
 * `isInvalid` and `isDisabled` cascade in from an enclosing `Field`, so
 * `<Field isDisabled>` dims it with nothing said here — and an explicit prop still
 * wins, in either direction.
 *
 * A haptic ticks on grab and as the value crosses a step, rate-limited by how far
 * the drag has travelled so a fine step scale reads as a cadence rather than a
 * buzz. `haptic={false}` silences it; a continuous slider never ticks.
 *
 * **A `vertical` slider needs a definite height from its parent** — it counts up
 * from the bottom and fills whatever it is given, so a wrapper with `h-48` or
 * `flex-1` is not optional.
 *
 * @example
 * <Slider defaultValue={30}>
 *   <Slider.Output />
 *   <Slider.Track>
 *     <Slider.Fill />
 *     <Slider.Thumb />
 *   </Slider.Track>
 * </Slider>
 *
 * @example
 * <Slider
 *   color="success"
 *   formatOptions={{ currency: "NZD", style: "currency" }}
 *   maxValue={1000}
 *   onChange={setPrice}
 *   step={10}
 *   value={price}
 * >
 *   <Slider.Output />
 *   <Slider.Track>
 *     {({ values }) => (
 *       <>
 *         <Slider.Fill />
 *         {values.map((_, index) => (
 *           <Slider.Thumb index={index} key={index} />
 *         ))}
 *       </>
 *     )}
 *   </Slider.Track>
 * </Slider>
 *
 * @example
 * <View className="h-48">
 *   <Slider defaultValue={40} orientation="vertical">
 *     <Slider.Track>
 *       <Slider.Fill />
 *       <Slider.Thumb />
 *     </Slider.Track>
 *   </Slider>
 * </View>
 */
export const Slider = Object.assign(SliderRoot, {
	/** The current value, formatted. Give it a function to label it yourself. */
	Output: SliderOutput,
	/** The groove the thumbs run along, and the surface the drag is claimed on. */
	Track: SliderTrack,
	/** The painted part of the groove, from the minimum — or between two thumbs. */
	Fill: SliderFill,
	/** The grab handle. `index` picks which value it drives in a range. */
	Thumb: SliderThumb,
	displayName: "DelacourUI.Slider",
});

import type { SliderOrientation } from "./slider.variants";

/**
 * What a render function inside a slider is handed.
 *
 * Shared by `Slider.Output` and `Slider.Track`, which is what puts it here rather
 * than in either one's own file — two consumers is the bar a `{name}.types.ts`
 * entry has to clear. See AGENTS.md.
 *
 * It carries the *settled* state, so a render function never has to know whether
 * an axis came from its own call site or from an enclosing `Field`.
 */
export type SliderRenderProps = {
	/** Every thumb's value, in the order the thumbs were given. */
	values: number[];
	minValue: number;
	maxValue: number;
	/** The increment the values snap to. `0` is continuous. */
	step: number;
	orientation: SliderOrientation;
	isDisabled: boolean;
	isInvalid: boolean;
};

/** A part whose children may be written out or computed from the slider's state. */
export type SliderRenderChildren = React.ReactNode | ((props: SliderRenderProps) => React.ReactNode);

import type { VariantProps } from "tailwind-variants";
import { tv } from "@registry/lib/tv";
import type { TextSize } from "@registry/ui/text/text.variants";

/** What a filled track means. Badge's and Checkbox's set, reusing tokens the theme already has. */
export const SLIDER_COLORS = ["default", "primary", "success", "warning", "danger", "info"] as const;

export const SLIDER_SIZES = ["sm", "md", "lg"] as const;

/** Which way the track runs. A `vertical` slider counts up from the bottom. */
export const SLIDER_ORIENTATIONS = ["horizontal", "vertical"] as const;

export type SliderColor = (typeof SLIDER_COLORS)[number];
export type SliderSize = (typeof SLIDER_SIZES)[number];
export type SliderOrientation = (typeof SLIDER_ORIENTATIONS)[number];

/**
 * The axes a slider falls back to when nothing names one.
 *
 * Named once because two places read them — `defaultVariants` below and
 * {@link resolveSliderAxes}, which runs before `tv` is ever called. A test pins
 * the pair, since a drift between them is a slider that renders at one size and
 * reports another.
 */
export const SLIDER_DEFAULT_COLOR: SliderColor = "default";
export const SLIDER_DEFAULT_SIZE: SliderSize = "md";
export const SLIDER_DEFAULT_ORIENTATION: SliderOrientation = "horizontal";

/** The range a slider covers when the caller names none. */
export const SLIDER_MIN_VALUE = 0;
export const SLIDER_MAX_VALUE = 100;

/** The increment a slider snaps to when the caller names none. `0` is continuous. */
export const SLIDER_STEP = 1;

/**
 * The spring the grabbed thumb grows on.
 *
 * Deliberately `Pressable`'s own `PRESS_SPRING`: a thumb responding to a touch is
 * the same event as a button responding to one, and two springs a frame apart
 * would read as two things happening.
 */
export const SLIDER_THUMB_SPRING = { damping: 18, mass: 0.4, stiffness: 320 } as const;

/**
 * How far the grabbed handle's knob travels on the scale axis.
 *
 * It **shrinks**, the way every other pressable in this library does, and it is
 * the *knob* that moves rather than the capsule around it. Scaling the capsule
 * would push it past the track it sits flush inside — a bulge on both edges every
 * time a finger lands. The knob is a descendant with padding to spare, so the
 * squeeze happens entirely within the handle's own footprint and the capsule
 * stays exactly where the value says it is.
 */
export const SLIDER_THUMB_ANIMATION = { restScale: 1, grabbedScale: 0.9 } as const;

/**
 * The `Text` size step each slider size hands its output.
 *
 * `Slider.Output` renders `Text.Label` and names this step rather than restating a
 * type scale in the `output` slot. `Text`'s own size axis is built to beat its
 * preset, so the weight and the colour stay in exactly one place — the preset —
 * while the readout still tracks the slider's size. A test asserts every value
 * here is a size `Text` actually has.
 */
export const SLIDER_OUTPUT_TEXT_SIZE: Record<SliderSize, TextSize> = { sm: "sm", md: "md", lg: "lg" };

/**
 * How far a drag must travel between two haptic ticks, in points.
 *
 * A pan updates at the display's refresh rate, so "tick whenever the snapped
 * value changed" is not a rate limit on its own: 0–100 in whole steps across a
 * 300pt track is a step every three points, and a flick crosses a hundred of them
 * in a fifth of a second. That is not a hundred ticks, it is a buzz — and a
 * hundred synchronous calls into the haptic engine to produce it.
 *
 * Gating on distance rather than on a clock keeps the rule pure, so `bun test`
 * reaches it, and makes it degrade the right way: a coarse step scale ticks on
 * every stop, and a fine one thins out to a cadence a hand can actually feel.
 */
export const SLIDER_HAPTIC_MIN_TRAVEL = 6;

/**
 * What sits between the two ends of a range in `Slider.Output`.
 *
 * An en dash, not a hyphen. A hyphen beside a negative number reads as arithmetic
 * — `-20 - -5` — and a range is exactly the case where that happens.
 */
export const SLIDER_RANGE_SEPARATOR = " – ";

/**
 * Styling for every part of a slider.
 *
 * One slotted `tv()` rather than a call per part, because `slider-track.tsx`,
 * `slider-fill.tsx` and `slider-thumb.tsx` cannot import the root without closing
 * a cycle (AGENTS.md rule 3) yet all three read the same `color`, `size` and
 * `orientation`.
 *
 * **The colour paints the fill, the capsule and the knob — never the groove.** An
 * empty track is the same chrome at every colour, the way an unticked checkbox is
 * `border-input bg-card` however it is coloured, and a test asserts that. The
 * capsule takes the fill's *own* colour so the two meet with no seam and the
 * handle reads as the leading end of the fill rather than as something sitting on
 * top of it; the knob is that colour's `-foreground`, which is what the token
 * means (rule 11) and what keeps it legible on all six. A single pale knob would
 * be unreadable on `warning`, and a test pins the pair rather than trusting two
 * maps to stay in step.
 *
 * **`default` and `primary` name different tokens that this theme tunes to the
 * same value.** `foreground` is the page's ink and `primary` is the brand's
 * action colour; they are `#262626` in both roles today, which is the situation
 * `Badge` already documents for its neutral end. Modelling them as one token
 * would be the drift, not the duplication: an app that re-themes `primary` to
 * blue wants `color="primary"` blue and `color="default"` still ink.
 *
 * **The handle is two nodes: a capsule and a knob.** The capsule carries the
 * colour, the size and the position; the knob is the pale bar inside it and the
 * only thing that moves when a finger lands. Two nodes rather than one because a
 * single view cannot be both the surface and the thing inset within it, and
 * because two animated styles on one node fight for the same prop — see
 * {@link SLIDER_THUMB_ANIMATION}.
 *
 * **Neither takes a shadow.** Nothing else in this package draws one, and React
 * Native's shadow props diverge between platforms in a way a flat fill does not.
 * A test pins that absence across the whole matrix. The capsule needs no border
 * either: it is a solid block of the fill's colour, so its edge is already the
 * boundary between the fill and the groove.
 *
 * **The capsule is flush across the track and longer along it**, and the flush
 * half is load-bearing rather than decorative. It is what lets {@link fillExtent}
 * land exactly on both extremes — one capsule's length of fill at the minimum, the
 * track's full length at the maximum — with no inset to leave stray colour at one
 * end and empty groove at the other. So the cross axis takes the track's own step
 * and a test asserts the two classes name the same one, while the long axis is two
 * steps up from it: a handle you can tell apart from the groove it runs in.
 *
 * Both are plain spacing steps rather than tokens: these are numbers read in one
 * component, the trade `Radio` already makes for the dot inside its ring.
 * `Checkbox` reads `--spacing-icon-*` for its square and should keep doing so — a
 * glyph in a box is a mark on the icon scale, where a slider's handle is the body
 * of the control itself.
 *
 * Because the two axes differ and only the orientation knows which is which, the
 * capsule's size lives in the same six compound cells as the track's thickness
 * rather than in a `size`-only variant.
 *
 * **The groove is not the touch target on its own.** A `sm` track is sixteen
 * points, so the drag is claimed on a transparent `touchArea` whose padding brings
 * it up to 44. The thickness and that padding live in the *same* compound cell
 * because they are one number — they sum to 44 at every size, and a test asserts
 * the sum rather than the parts. Split across two variants, a retune of the
 * thickness silently shrinks the target.
 *
 * That padding is on the **cross axis only**. The two boxes therefore share an
 * origin along the axis the value is measured on, which is what lets the pan read
 * its offset straight off the touch without correcting for a gutter it cannot see.
 * Pad the main axis and every value is wrong by the padding, silently, and
 * visibly only at the ends.
 *
 * **The track still centres the thumb, and now has nothing to centre.** An
 * absolutely-positioned child with no cross-axis inset is placed at the static
 * position the parent's `items-center` decides — which did the work when the thumb
 * overhung a hairline groove, and is a no-op now that the two are the same size.
 * It stays because the moment those sizes are allowed to differ it is load-bearing
 * again, and because it is why the track is `flex-row` when horizontal:
 * `items-center` centres on the *cross* axis, and a column track would centre the
 * wrong one.
 *
 * **The fade lands on the root**, which is a plain `View` here rather than a
 * `Pressable` — so unlike `Radio`, an `opacity-50` class on it is not overwritten
 * by an animated style writing `opacity` every frame.
 *
 * No slot worn by a `View` carries `text-*` or `font-*`: `Slider.Output` renders
 * a `Text` preset and names a step — see {@link SLIDER_OUTPUT_TEXT_SIZE}.
 *
 * Free of React Native imports so it stays unit-testable — `bun test` cannot parse
 * React Native's Flow-typed source. See AGENTS.md.
 */
export const sliderVariants = tv({
	slots: {
		/** The column holding the readout and the track. */
		root: "",
		/** Handed to a `Text.Label`. Layout only, and today there is none. */
		output: "",
		/** The transparent box the drag is claimed on. Padded on the cross axis only. */
		touchArea: "items-center justify-center",
		/** The groove. Positions the fill and the thumbs inside it. */
		track: "relative items-center rounded-full bg-secondary",
		/** The painted part of the groove. Its extent is an animated style, never a class. */
		fill: "absolute rounded-full",
		/** The handle's capsule. Painted in the fill's own colour, so the two join seamlessly. */
		thumb: "absolute justify-center rounded-full p-0.5",
		/** The pale bar inside the capsule, and the only part that moves under a finger. */
		knob: "flex-1 rounded-full",
	},
	variants: {
		orientation: {
			horizontal: {
				root: "w-full gap-2",
				touchArea: "w-full flex-row",
				track: "w-full flex-row",
				fill: "bottom-0 top-0",
				thumb: "left-0",
			},
			vertical: {
				root: "h-full items-center gap-2",
				touchArea: "h-full flex-col",
				track: "h-full justify-end",
				fill: "left-0 right-0",
				thumb: "bottom-0",
			},
		},
		// Empty because a capsule's two axes differ and only the orientation knows
		// which is which — the six cells below carry both. Declared anyway so `size`
		// stays a variant `tv` can type and default.
		size: { sm: {}, md: {}, lg: {} },
		// The empty branches are load-bearing typing, not placeholders. `tv` derives
		// the prop type from the declared keys, so a map with only `true` types the
		// prop as `true` rather than `boolean`.
		color: { default: {}, primary: {}, success: {}, warning: {}, danger: {}, info: {} },
		isInvalid: { true: {}, false: {} },
		isDisabled: { true: { root: "opacity-50" }, false: {} },
	},
	compoundVariants: [
		// The groove's thickness is the one measurement that has to know the
		// orientation, because it is the *cross* axis of whichever way the track
		// runs. Six cells rather than a second size scale, so the two orientations
		// cannot drift to different weights.
		//
		// The touch padding rides in the same cell, because the two are one number:
		// they sum to 44pt at every size, and splitting them across two variants is
		// how a retune of the thickness silently shrinks the target.
		{ orientation: "horizontal", size: "sm", class: { track: "h-4", touchArea: "py-3.5", thumb: "h-4 w-6" } },
		{ orientation: "horizontal", size: "md", class: { track: "h-5", touchArea: "py-3", thumb: "h-5 w-7" } },
		{ orientation: "horizontal", size: "lg", class: { track: "h-6", touchArea: "py-2.5", thumb: "h-6 w-8" } },
		{ orientation: "vertical", size: "sm", class: { track: "w-4", touchArea: "px-3.5", thumb: "w-4 h-6" } },
		{ orientation: "vertical", size: "md", class: { track: "w-5", touchArea: "px-3", thumb: "w-5 h-7" } },
		{ orientation: "vertical", size: "lg", class: { track: "w-6", touchArea: "px-2.5", thumb: "w-6 h-8" } },
		// `color` is the only axis painting these three, so its six cells could be a
		// plain variant. They are compounds so that `isInvalid` below, emitted after
		// them, can beat every one — the ordering `Radio` leans on for its ring.
		//
		// The capsule takes the fill's own colour rather than a chrome of its own, so
		// the two meet with no seam and the handle reads as the leading end of the
		// fill rather than as something sitting on top of it. The knob is that
		// colour's `-foreground`, which is what the token means (rule 11) and what
		// keeps it legible on all six.
		{ color: "default", class: { fill: "bg-foreground", thumb: "bg-foreground", knob: "bg-background" } },
		{ color: "primary", class: { fill: "bg-primary", thumb: "bg-primary", knob: "bg-primary-foreground" } },
		{ color: "success", class: { fill: "bg-success", thumb: "bg-success", knob: "bg-success-foreground" } },
		{ color: "warning", class: { fill: "bg-warning", thumb: "bg-warning", knob: "bg-warning-foreground" } },
		{ color: "danger", class: { fill: "bg-danger", thumb: "bg-danger", knob: "bg-danger-foreground" } },
		{ color: "info", class: { fill: "bg-info", thumb: "bg-info", knob: "bg-info-foreground" } },
		// Invalid outranks the colour, the way it does on a checkbox's border. A
		// slider that stayed green while its value was rejected would drop its only
		// signal exactly while the value is being corrected.
		{ isInvalid: true, class: { fill: "bg-danger", thumb: "bg-danger", knob: "bg-danger-foreground" } },
	],
	defaultVariants: {
		color: SLIDER_DEFAULT_COLOR,
		size: SLIDER_DEFAULT_SIZE,
		orientation: SLIDER_DEFAULT_ORIENTATION,
		isInvalid: false,
		isDisabled: false,
	},
});

/**
 * The caller's value, as the array every part reads.
 *
 * Always a copy: the array is handed to a shared value and written on the UI
 * thread, and aliasing the caller's own would mutate state they still hold.
 */
export function toValueArray(value: number | number[]): number[] {
	"worklet";
	return Array.isArray(value) ? [...value] : [value];
}

/**
 * The array, back in the shape the caller passed in.
 *
 * A slider given a number reports a number; one given an array reports an array.
 * `isRange` is locked on first render rather than sniffed per call — see
 * `slider.tsx` — so the shape a caller receives never changes under them.
 */
export function fromValueArray(values: readonly number[], isRange: boolean): number | number[] {
	if (isRange) return [...values];
	return values[0] ?? 0;
}

/**
 * Where a value sits on the track, as 0–1.
 *
 * Clamped rather than extrapolated, and `0` for a degenerate range — a slider
 * whose minimum equals its maximum has one position, and dividing by the
 * difference would put `NaN` into a shared value and freeze the thumb for good.
 */
export function progressOf(value: number, minValue: number, maxValue: number): number {
	"worklet";
	const span = maxValue - minValue;
	if (span <= 0) return 0;
	const ratio = (value - minValue) / span;
	return ratio < 0 ? 0 : ratio > 1 ? 1 : ratio;
}

/**
 * The nearest reachable value, measured in steps **from the minimum**.
 *
 * Not from zero: a slider from 5 to 100 in tens reaches 5, 15, 25 — the stops a
 * caller can actually land on — rather than 10, 20, 30 with an unreachable 5 at
 * the end.
 *
 * **Both ends are always stops, even when the step does not divide the range.**
 * 0–100 by 7 reaches 0, 7, 14 … 98 and then 100, because a slider whose maximum
 * cannot be reached by dragging all the way to the end is a slider that lies about
 * its own range — the caller wrote `maxValue`, and the last two points of travel
 * are not where they get told it was unreachable. A tie goes to the regular stop,
 * so the extra one only ever appears at the very end of the drag.
 *
 * `step <= 0` means continuous and passes the clamped value through.
 *
 * The final rounding kills binary floating-point noise: ten steps of `0.1` land on
 * `0.30000000000000004` without it, which a formatted readout shows in full.
 */
export function snapToStep(value: number, step: number, minValue: number, maxValue: number): number {
	"worklet";
	const clamped = value < minValue ? minValue : value > maxValue ? maxValue : value;
	if (step <= 0) return clamped;

	const snapped = minValue + Math.round((clamped - minValue) / step) * step;
	const bounded = snapped < minValue ? minValue : snapped > maxValue ? maxValue : snapped;
	const rounded = Math.round(bounded * 1e10) / 1e10;

	return Math.abs(clamped - maxValue) < Math.abs(clamped - rounded) ? maxValue : rounded;
}

/**
 * One thumb's value, held inside the range and inside its own neighbours.
 *
 * The outer thumbs are bounded by the range; an inner one by the thumbs either
 * side of it. This is the whole of what makes a range a range — without it a drag
 * past a neighbour reorders the values and the fill inverts.
 */
export function clampThumb(
	value: number,
	values: readonly number[],
	index: number,
	minValue: number,
	maxValue: number
): number {
	"worklet";
	const lower = index > 0 ? (values[index - 1] ?? minValue) : minValue;
	const upper = index < values.length - 1 ? (values[index + 1] ?? maxValue) : maxValue;
	const floor = lower < minValue ? minValue : lower;
	const ceiling = upper > maxValue ? maxValue : upper;
	return value < floor ? floor : value > ceiling ? ceiling : value;
}

/**
 * The value a touch at `position` points at.
 *
 * `position` is the touch's offset along the track with the thumb's own half-width
 * already taken off, and `travel` is what the thumb's leading edge can cover —
 * `trackSize - thumbSize`. Working in the thumb's own frame is what keeps the
 * handle inside the groove at both ends instead of overhanging them.
 *
 * **A vertical track is inverted here**, and in exactly one other place — the sign
 * of the thumb's translate. A touch offset is measured from the top and a vertical
 * slider counts up from the bottom, so one of the two has to turn around, and one
 * place deciding it is what keeps them agreeing.
 *
 * `travel <= 0` returns the minimum rather than dividing: the track reports its
 * size on layout, so every frame before the first one has nothing to divide by.
 */
export function valueFromOffset({
	position,
	travel,
	minValue,
	maxValue,
	isVertical,
}: {
	position: number;
	travel: number;
	minValue: number;
	maxValue: number;
	isVertical: boolean;
}): number {
	"worklet";
	if (travel <= 0) return minValue;

	const raw = position / travel;
	const oriented = isVertical ? 1 - raw : raw;
	const ratio = oriented < 0 ? 0 : oriented > 1 ? 1 : oriented;
	return minValue + ratio * (maxValue - minValue);
}

/**
 * Which thumb a touch grabs.
 *
 * A tie resolves to the lower index, and it has to resolve to *something* fixed:
 * pressing the exact midpoint between two thumbs is a real gesture, and which one
 * moves must not depend on iteration order changing under a refactor.
 */
export function nearestThumbIndex(values: readonly number[], target: number): number {
	"worklet";
	let nearest = 0;
	let shortest = Number.POSITIVE_INFINITY;

	for (let index = 0; index < values.length; index++) {
		const distance = Math.abs((values[index] ?? 0) - target);
		if (distance < shortest) {
			shortest = distance;
			nearest = index;
		}
	}

	return nearest;
}

/**
 * The stretch of track the fill covers, as two 0–1 positions.
 *
 * A lone thumb fills from the minimum, because that is what a single value means:
 * how far along. A range fills *between* its own thumbs, because the ends are what
 * the caller excluded.
 *
 * The outermost thumbs are taken by value rather than by index, so a caller who
 * hands over a descending array still gets a fill with a positive extent instead
 * of one drawn backwards. The drag itself keeps them in order — see
 * {@link clampThumb} — but the first render happens before any drag.
 */
export function fillBounds(
	values: readonly number[],
	minValue: number,
	maxValue: number
): { start: number; end: number } {
	"worklet";
	const span = maxValue - minValue;
	if (values.length === 0 || span <= 0) return { start: 0, end: 0 };

	let lowest = values[0] ?? minValue;
	let highest = lowest;
	for (const value of values) {
		if (value < lowest) lowest = value;
		if (value > highest) highest = value;
	}

	// The progress maths is written out rather than calling `progressOf`. A
	// module-scope worklet calling another one binds its closure once, at module
	// init, in source order — so the pair works only while the callee happens to be
	// declared first, and a tidy-up that reorders the file crashes the UI thread
	// with `undefined is not a function`. Every exported worklet here stays flat,
	// which is the conclusion `screen.variants.ts` reached the hard way.
	const start = values.length > 1 ? Math.min(Math.max((lowest - minValue) / span, 0), 1) : 0;
	const end = Math.min(Math.max((highest - minValue) / span, 0), 1);

	return { start, end: Math.max(start, end) };
}

/**
 * The fill's box in points: where it starts along the track, and how long it is.
 *
 * Takes {@link fillBounds}' two 0–1 positions into the track's own frame. It is a
 * function rather than four lines inside `slider-fill.tsx` because the property it
 * encodes is not self-evident and is the whole reason the thumb is drawn the size
 * it is — a `+ thumbSize` at the far end, which lands exactly on both extremes:
 *
 * - at the **minimum** the extent is one thumb, so the handle covers the fill
 *   completely and a slider at rest shows a plain track;
 * - at the **maximum** the extent is `travel + thumbSize`, the track's full
 *   length, with no sliver of empty groove past the handle;
 * - a **collapsed range** is one thumb wide rather than zero, so the fill does not
 *   blink out from under two thumbs dragged together.
 *
 * All three hold only because the thumb's diameter equals the track's thickness.
 * Inset the thumb inside the track and every one of them is off by the inset — a
 * few points of stray colour at one end and of empty groove at the other, at every
 * size. This is the arithmetic that pays for that proportion, so it is the
 * arithmetic `bun test` has to be able to reach.
 *
 * It replaced a `+ thumbSize / 2`, which stopped the fill at the thumb's *centre*.
 * That was correct but invisible while a large disc overhung a hairline groove; it
 * would now leave the last half-thumb of the bar unfilled, in plain view.
 *
 * `travel <= 0` draws nothing: a measured `0` means *not measured yet*, and a bar
 * sized off it would flash at a garbage length on the frame before layout lands.
 */
export function fillExtent({
	start,
	end,
	travel,
	thumbSize,
	isRange,
}: {
	start: number;
	end: number;
	travel: number;
	thumbSize: number;
	isRange: boolean;
}): { offset: number; extent: number } {
	"worklet";
	if (travel <= 0) return { offset: 0, extent: 0 };

	const from = isRange ? Math.min(Math.max(start, 0), 1) : 0;
	const to = Math.min(Math.max(end, 0), 1);
	const offset = from * travel;
	const extent = Math.max(to * travel + thumbSize - offset, thumbSize);

	return { offset, extent };
}

/**
 * The values as one readable string.
 *
 * JS-thread only — `Intl` is not available to a worklet, which is the reason
 * `Slider.Output` reads React state rather than the shared value the thumb reads.
 */
export function formatSliderValue(values: readonly number[], formatOptions?: Intl.NumberFormatOptions): string {
	if (values.length === 0) return "";
	const format = new Intl.NumberFormat(undefined, formatOptions);
	return values.map((value) => format.format(value)).join(SLIDER_RANGE_SEPARATOR);
}

/**
 * Whether crossing into `snapped` should tick.
 *
 * Four rules, in order:
 *
 * - a **continuous** slider never ticks. There is no stop to land on, so a tick
 *   would be reporting the refresh rate rather than the value.
 * - a value that did not change does not tick.
 * - either **end of the range** always ticks, however fast the drag arrived. It
 *   is the one moment a slider has something to say that the screen does not
 *   already show — the thumb has stopped and the finger has not.
 * - otherwise the drag must have travelled {@link SLIDER_HAPTIC_MIN_TRAVEL}
 *   points since the last tick.
 *
 * Pure, so the whole ladder is reachable from `bun test`, and flat, so it is safe
 * to call from the pan's worklet. See AGENTS.md.
 */
export function shouldTickHaptic({
	step,
	snapped,
	lastSnapped,
	position,
	lastPosition,
	minValue,
	maxValue,
}: {
	step: number;
	snapped: number;
	lastSnapped: number;
	position: number;
	lastPosition: number;
	minValue: number;
	maxValue: number;
}): boolean {
	"worklet";
	if (step <= 0) return false;
	if (snapped === lastSnapped) return false;
	if (snapped === minValue || snapped === maxValue) return true;
	return Math.abs(position - lastPosition) >= SLIDER_HAPTIC_MIN_TRAVEL;
}

/** What a slider was given at its own call site. */
export type SliderOwnAxes = {
	color?: SliderColor;
	size?: SliderSize;
	orientation?: SliderOrientation;
	isDisabled?: boolean;
	isInvalid?: boolean;
};

/** What an enclosing `Field` publishes, or null outside one. */
export type SliderFieldAxes = { isDisabled?: boolean; isInvalid?: boolean };

/** Every axis settled, ready to hand to {@link sliderVariants} and to context. */
export type SliderAxes = Required<SliderOwnAxes>;

/**
 * Settles a slider's axes from the two places they can come from.
 *
 * There is no `Slider.Group`, so the ladder is two rungs rather than three: the
 * slider's own props, then an enclosing `Field`. A slider inside `<Field isDisabled>`
 * dims with nothing said at the call site, and `isDisabled={false}` opts that one
 * out — `??` throughout and never `||`, so an explicit `false` is a value rather
 * than an absence.
 *
 * A `Field` reaches the two *state* axes only. It carries no colour, size or
 * orientation, and a test pins that it cannot acquire one by accident.
 *
 * Pure, so the whole matrix is reachable from `bun test`. See AGENTS.md.
 */
export function resolveSliderAxes({ own, field }: { own?: SliderOwnAxes; field?: SliderFieldAxes | null }): SliderAxes {
	return {
		color: own?.color ?? SLIDER_DEFAULT_COLOR,
		size: own?.size ?? SLIDER_DEFAULT_SIZE,
		orientation: own?.orientation ?? SLIDER_DEFAULT_ORIENTATION,
		isDisabled: own?.isDisabled ?? field?.isDisabled ?? false,
		isInvalid: own?.isInvalid ?? field?.isInvalid ?? false,
	};
}

export type SliderVariantProps = VariantProps<typeof sliderVariants>;
